from math import floor
class Solution:
    def maxAlternatingSum(self, nums: list[int]) -> int:
        start = 0
        limit = False
        if 1 <= len(nums) <= 10**5:
            limit == True
        
        if not nums or not limit:
            return 0
        
        #! TAKE ABS VALS TO PREVENT LOSS
        self.absol_list = []
        
        for i in nums:
            self.absol_list.append(abs(i))

        #! SORT AFTER ABSOLUTION
        self.absol_list.sort()
        print(self.absol_list)
        absol_len = int(len(self.absol_list))
        
        #* PARTITION
        if absol_len % 2 == 0:            
            print("list length is even, two same length sub-parts will be created")
            #LEN
            sub_part_len = absol_len//2
            # SUB-INDEXES
            index = sub_part_len
            # SUB-PARTS
            min_subpart = self.absol_list[0:index:1]
            max_subpart = self.absol_list[index::1]
            print(f"min_subpart: {min_subpart} \nmax_subpart: {max_subpart}")
            for a,b in zip(min_subpart, reversed(max_subpart)):
                result1 = start + (b**2 - a**2)
                start = result1
                print(f"result is:{result1}")
            print(f"result is:{result1}")
            return result1
        else:
            result2 = start
            print("list length is odd, the sub-parts will be:\nmin=max+1")
            sub_part_len = int(len(self.absol_list)//2)
            index = floor(sub_part_len) + 1

            min_subpart = self.absol_list[0:index:1]
            max_subpart = self.absol_list[index::1]
            print(f"min_subpart: {min_subpart} \nmax_subpart: {max_subpart}")
            for a,b in zip(min_subpart, reversed(max_subpart)):
                result2 = start + (b**2 - a**2)
                start = result2
            result2 += min_subpart[-1]**2
            print(f"result is:{result2}")
            return result2
